use tron_consensus::{java_fork_pass,maintenance_reset,solidity_position,update_fork,ForkSpec,ForkState};
#[test] fn sorted_solidity_index_is_java_floor_thirty_percent(){assert_eq!(solidity_position(27),8);assert_eq!(solidity_position(1),0);let mut heights=vec![10,1,7,8,3,2,9,4,6,5];heights.sort_unstable();assert_eq!(heights[solidity_position(heights.len())],4);}
#[test] fn fork_update_uses_canonical_evaluator_and_maintenance_reset(){let spec=ForkSpec{version:6,hard_fork_time:100,rate_percent:70};let evaluator=|s:&ForkSpec,b:&[u8]|java_fork_pass(s,120,10,b);let active=vec![vec![1],vec![2],vec![3]];let mut state=ForkState::default();for producer in &active{update_fork(&mut state,std::slice::from_ref(&spec),&active,producer,6,&evaluator);}let outcome=update_fork(&mut state,std::slice::from_ref(&spec),&active,&active[0],6,&evaluator);assert!(outcome.activated);assert_eq!(state.latest_version,6);state.latest_version=0;state.stats.insert(6,vec![1,0,0]);maintenance_reset(&mut state,&[spec],2,&evaluator);assert_eq!(state.stats[&6],vec![0,0]);}
